def merge_intervals(pairs):
    out = []
    for start, end in sorted(pairs):
        if out and start <= out[-1][1]:
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

alt:
def merge_intervals(pairs):
    pairs = sorted(pairs)
    out = []
    for p in pairs:
        if not out or p[0] > out[-1][1]:
            out.append([p[0], p[1]])
        elif p[1] > out[-1][1]:
            out[-1][1] = p[1]
    return out
